import React, { FormEvent, useState } from 'react';

import { changeAvatarInModal } from '@helpers/changeAvatarModal';
import { err, success } from '@helpers/notificationHelper';
import PohButton, { ButtonVariant } from '@ui-kit/Button';
import PohInput, { InputTypes } from '@ui-kit/Input';
import PohCol from '@ui-kit/layout/Col';
import PohContainer from '@ui-kit/layout/Container';
import PohRow from '@ui-kit/layout/Row';
import PohLink from '@ui-kit/Link';

import nophoto from '../../../../img/nophoto.png';
import { addBackpackAsync } from '../../@services/equip.service';
import { IBackpack } from '../../@types/equip.types';

interface IBackpackEditorProps {
  backpack?: IBackpack;
  onSave: (backpack: IBackpack) => void;
  onCancel: () => void;
}

const BackpackEditor: React.FC<IBackpackEditorProps> = ({
  backpack: defaultBackpack,
  onSave,
  onCancel,
}) => {
  const [data, setData] = useState<IBackpack>(
    defaultBackpack ?? {
      id: 0,
      name: '',
      photo: '',
      weight: 0,
      value: 0,
    },
  );

  const handleSave = async () => {
    try {
      const id = await addBackpackAsync(data);
      success(id !== data.id ? 'Добавлено' : 'Сохранено');
      const updatedModel = { ...data, id };
      setData(updatedModel);
      onSave(updatedModel);
    } catch (e) {
      err(e as Error);
    }
  };

  const handleInputChange =
    <K extends keyof IBackpack>(field: keyof IBackpack) =>
    (value: IBackpack[K]) => {
      setData((fd) => ({
        ...(fd as IBackpack),
        [field]: value,
      }));
    };

  return (
    <PohContainer
      as="form"
      onSubmit={(e: FormEvent) => {
        e.preventDefault();
        handleSave();
      }}
    >
      <PohRow>
        <PohCol sm={8}>
          <PohInput
            label="Название рюкзака"
            name="backpack"
            autoComplete="backpack-name"
            value={data.name}
            onChange={handleInputChange('name')}
            required
          />
          <PohInput
            label="Вес пустого рюкзака, кг"
            type={InputTypes.number}
            min={0}
            max={10}
            step={0.01}
            maxLength={5}
            value={data.weight < 0 ? '' : data.weight.toString()}
            onChange={(v) => handleInputChange('weight')(v ? +v : -1)}
            required
          />
          <PohInput
            label="Объем рюкзака, л."
            type={InputTypes.number}
            min={10}
            max={150}
            step={5}
            maxLength={3}
            value={data.value < 0 ? '' : data.value.toString()}
            onChange={(v) => handleInputChange('value')(v ? +v : -1)}
            required
          />
        </PohCol>
        <PohCol sm={4}>
          <PohLink
            onClick={() => {
              changeAvatarInModal(
                {
                  width: 240,
                  height: 320,
                  folder: 'images/backpacks/',
                },
                (src) => {
                  src && handleInputChange('photo')(src);
                },
              );
            }}
          >
            <img src={data.photo || nophoto} width="100%" alt="Рюкзак" />
          </PohLink>
        </PohCol>
      </PohRow>
      <footer className="mt-4">
        <PohButton variant={ButtonVariant.Secondary} onClick={onCancel}>
          Отмена
        </PohButton>{' '}
        &nbsp;
        <PohButton variant={ButtonVariant.Primary} type="submit">
          Сохранить
        </PohButton>
      </footer>
    </PohContainer>
  );
};

export default BackpackEditor;
