import React from 'react';

import { showModal } from '@ui-kit/Modal';

import BackpackEditor from './index';
import { IBackpack } from '../../@types/equip.types';

export async function addBackpackAsync(): Promise<IBackpack> {
  return new Promise((resolve) => {
    showModal({
      children: (handleClose: () => void) => (
        <BackpackEditor
          onCancel={handleClose}
          onSave={(data) => {
            resolve(data);
            handleClose();
          }}
        />
      ),
    });
  });
}

export async function editBackpackAsync(backpack: IBackpack): Promise<IBackpack> {
  return new Promise((resolve) => {
    showModal({
      children: (handleClose: () => void) => (
        <BackpackEditor
          backpack={backpack}
          onCancel={handleClose}
          onSave={(data) => {
            resolve(data);
            handleClose();
          }}
        />
      ),
    });
  });
}
